     1	const R_KM = 6371;
     2	const rad = (d) => (d * Math.PI) / 180;
     3	
     4	function haversineKm([lng1, lat1], [lng2, lat2]) {
     5	  const a = Math.sin(rad(lat2 - lat1) / 2) ** 2 + Math.cos(rad(lat1)) * Math.cos(rad(lat2)) * Math.sin(rad(lng2 - lng1) / 2) ** 2;
     6	  return 2 * R_KM * Math.asin(Math.sqrt(a));
     7	}
     8	
     9	function toLngLat(lat, lng) {
    10	  return [Number(lng), Number(lat)];
    11	}
    12	
    13	module.exports = { haversineKm, toLngLat };

